#include "KS/SRC/ks/FEPanel_shared.h"

#define MAX_CHEATS_PER_SCREEN 2

class FEMenuEntry;
class GraphicalMenuSystem;
class PanelQuad;

class FEMultiMenu
{
    char built_layout[0x160];
};

class CheatCodeMenu : public FEMultiMenu
{
private:
    FEMenuEntry *cheats[MAX_CHEATS_PER_SCREEN];
    int menu_entry_cheat_index[MAX_CHEATS_PER_SCREEN];
    GraphicalMenuSystem *sys;
    int next_down, next_up;
    TextString *toggle_state[MAX_CHEATS_PER_SCREEN];
    PanelQuad *arrow_up;
    PanelQuad *arrow_down;

    void ResetToggles();
};

class Cheat
{
private:
    bool locked;
    bool on;

public:
    bool isOn() const { return on; }
};

enum
{
    CHEAT_LAST = 22,
    GT_FE_MENU_OP_ON = 178,
    GT_FE_MENU_OP_OFF
};

extern Cheat g_session_cheats[CHEAT_LAST];
extern stringx ksGlobalTextArray[];

asm(".equ g_session_cheats, 0x0042BD48");
asm(".equ ksGlobalTextArray, 0x003E6050");

void CheatCodeMenu::ResetToggles()
{
    for(int i = 0; i < MAX_CHEATS_PER_SCREEN; i++)
    {
        if(menu_entry_cheat_index[i] != -1)
        {
            if(g_session_cheats[menu_entry_cheat_index[i]].isOn())
                toggle_state[i]->changeText(ksGlobalTextArray[GT_FE_MENU_OP_ON]);
            else
                toggle_state[i]->changeText(ksGlobalTextArray[GT_FE_MENU_OP_OFF]);
        }
        else
            toggle_state[i]->changeText("");
    }
}
